    });

    const updatedTempRefId = updatedTempRef.data.node_id;
    if (!updatedTempRefId) {
      throw new Error(
        `Failed to force update temporary branch "${tempBranch}"`,
      );
    }

    return { tempRefId: updatedTempRefId };
  }
