import json, re
from collections import Counter

files = [l.strip() for l in open('/tmp/recent_transcripts.txt') if l.strip()]
bash_counter = Counter()
mcp_counter = Counter()

def leading_cmd(cmd):
    cmd = cmd.strip()
    # strip env assignments prefix like FOO=bar cmd
    parts = cmd.split()
    i = 0
    while i < len(parts) and re.match(r'^[A-Za-z_][A-Za-z0-9_]*=', parts[i]):
        i += 1
    parts = parts[i:]
    if not parts:
        return None
    first = parts[0]
    if first in ('sudo', 'timeout'):
        parts = parts[1:]
        # timeout takes a duration arg
        if first == 'timeout' and parts:
            parts = parts[1:]
        if not parts:
            return None
        first = parts[0]
    # take first two tokens as command+subcommand candidate
    second = parts[1] if len(parts) > 1 and not parts[1].startswith('-') else None
    return first, second

for fp in files:
    try:
        with open(fp, 'r', errors='ignore') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except Exception:
                    continue
                msg = obj.get('message', {})
                content = msg.get('content')
                if not isinstance(content, list):
                    continue
                for item in content:
                    if not isinstance(item, dict):
                        continue
                    if item.get('type') != 'tool_use':
                        continue
                    name = item.get('name', '')
                    inp = item.get('input', {}) or {}
                    if name == 'Bash':
                        cmd = inp.get('command', '')
                        if not cmd:
                            continue
                        # split on pipe/&&/; and take first segment only for leading command
                        first_seg = re.split(r'\||&&|;', cmd)[0].strip()
                        res = leading_cmd(first_seg)
                        if res:
                            first, second = res
                            key = f"{first} {second}" if second else first
                            bash_counter[key] += 1
                    elif name.startswith('mcp__'):
                        mcp_counter[name] += 1
    except Exception as e:
        pass

print("=== BASH ===")
for k, v in bash_counter.most_common(60):
    print(f"{v}\t{k}")
print("=== MCP ===")
for k, v in mcp_counter.most_common(30):
    print(f"{v}\t{k}")
