281	fn resolve_changeset_entry<R: CommandRunner, D: DependencyResolver>(
282	    workspace: &Workspace<'_, R, D>,
283	    raw: &str,
284	) -> Result<Vec<ReleasePackageId>, GraphError> {
285	    if raw.contains('/') {
286	        let id = ReleasePackageId::parse(raw).map_err(|_error| GraphError::ReleaseIntentStale)?;
287	        let known = workspace.graph.packages().any(|package| {
288	            package
289	                .canonical_manifests()
290	                .any(|manifest| manifest.ecosystem() == id.ecosystem() && package.id.name() == id.name())
291	        });
292	        return known.then_some(vec![id]).ok_or(GraphError::ReleaseIntentStale);
293	    }
294	
295	    let packages = workspace
296	        .graph
297	        .packages()
298	        .filter(|package| package.id.name() == raw)
299	        .collect::<Vec<_>>();
300	    if packages.len() != 1 {
301	        return Err(GraphError::ReleaseIntentStale);
302	    }
303	    packages[0]
304	        .canonical_manifests()
305	        .map(|manifest| {
306	            ReleasePackageId::new(manifest.ecosystem(), packages[0].id.name())
307	                .map_err(|_error| GraphError::ReleaseIntentStale)
308	        })
