122	        String::from_utf8_lossy(&version.stderr)
123	    );
124	
125	    // `version` writes the reviewed manifest and changelog edits.  The release
126	    // PR, rather than an intermediate local command, consumes its exact
127	    // changeset when that PR is merged.  Model that merge boundary explicitly:
128	    // the parent contains the authority and the merge commit deletes it.
129	    for entry in fs::read_dir(root.join(".changeset")).unwrap() {
130	        let path = entry.unwrap().path();
131	        if path.file_name().is_some_and(|name| name != "README.md")
132	            && path.extension().is_some_and(|extension| extension == "md")
133	        {
134	            fs::remove_file(path).unwrap();
135	        }
136	    }
137	    git(root, &["add", "-A"]);
138	    git(root, &["commit", "-m", "release core-crate 0.2.0"]);
139	    let release_commit = git(root, &["rev-parse", "HEAD"]);
140	    // GitHub Actions checks out the merge commit detached.  Git-commit trust
141	    // deliberately requires that topology, rather than accepting a mutable
142	    // branch ref as release authority.
143	    git(root, &["checkout", "--detach", &release_commit]);
144	    (dir, release_commit)
