116	    }
117	    let canonical = candidate.canonicalize().map_err(|error| GraphError::ArtifactRead {
118	        path: candidate.clone(),
119	        message: error.to_string(),
120	    })?;
121	    if !canonical.starts_with(root) {
122	        return Err(GraphError::UnsafeArtifactPath {
123	            path: canonical,
