248	    pub fn from_groups(fixed: Vec<GroupDef>, linked: Vec<GroupDef>) -> Self {
249	        let mut f_map = BTreeMap::new();
250	        let mut l_map = BTreeMap::new();
251	        let mut f_of = BTreeMap::new();
252	        let mut l_of = BTreeMap::new();
253	
254	        for g in fixed {
255	            for m in g.members(GroupMemberKind::Package) {
256	                if let GroupMember::Package(ref id) = m {
257	                    f_of.insert(id.clone(), g.name.clone());
258	                }
259	            }
260	            f_map.insert(g.name.clone(), g);
261	        }
262	
263	        for g in linked {
264	            for m in g.members(GroupMemberKind::Package) {
265	                if let GroupMember::Package(ref id) = m {
266	                    l_of.insert(id.clone(), g.name.clone());
267	                }
268	            }
269	            l_map.insert(g.name.clone(), g);
270	        }
271	
272	        GroupTable {
273	            fixed: f_map,
274	            linked: l_map,
275	            fixed_of: f_of,
276	            linked_of: l_of,
